function [DF, F, returnedID, MB] = LMS_gradient_regularized(w, xb, db, inputID)

% Function dedicated to compute the gradient cost function and the
% cost function value in the general case of minibatch of size MB >= 1.
%
% Usage: [DF, F,returnedID, MB] = LMS_gradient_regularized(w, xb, db, inputID)
% 
% where:
% - w: is the current ROW weight vector. It is the current LOCAL row vector of
%      the LMS weights as LOCALLY computed by the calling coworker
% - xb: is the new input batch ROW vector. It is the current vector of the
%       noisy observations, e.g., noisy features, generated by the calling
%       coworker;
% - db: is the desired SCALAR label;
% - DF: is the computed gradient ROW vector;
% - F: is the loss function SCALAR value. The default setting is the squared error loss 
% - inputID: ID of the calling coworker;
% - returnedID: echoes inputID 
%-  MB: minibatch size. It is always equal to length(w)


%----------Initial check------------------------------------------------
returnedID = inputID;
%--------------------------------------------------------------------------
[r, MB] = size(xb);


y = (1/MB)*xb*(w)';
%Estimated scalar label. 
%It implements the input-output relationship of the trained ML network. It needs of the machine model.
%It is scaled by MB, in order to allow an asymptotically exact estimate for
%MB->Inf at every finite and positive SNR.

e = db - y; 
%Compute the current (scalar) error between desired and actual machine output.

DF = (-2 * e*(1/MB)*xb) + ((10^-5)*(2*((MB-1)/(MB^2))*w));%OK
%Compute the current stochastic gradient.
%New generated row gradient vector under regularization and scaling by MB 
%It is the vector gradient of the following REGULARIZED 
%training loss function: (e^2) + ((10^-5)*((MB-1)/(MB^2)*(w*w'))
%
F  = (e^2);
%Squared error training loss
%Compute the current value of the adopted training loss function.
%Current LOCAL (scalar) squared error of the LMS algorithm implemented by the calling coworker
%
end %End function 
